"""Shared release download links for the canonical static manual."""
from pathlib import Path
import html,json
SITE=Path(__file__).resolve().parents[2]/'docs/manual'
def release_downloads():
 data=json.loads((SITE/'data/release.json').read_text(encoding='utf-8'))
 rows=''.join('<tr><td>'+html.escape(p['platform'])+'</td><td><a href="'+html.escape(p['url'],quote=True)+'">Download ZIP</a></td><td>'+format(p['bytes']/1_000_000,'.2f')+' MB</td><td>'+html.escape(p['scope'])+'</td></tr>' for p in data['packages'])
 return '<style>.manual-release-downloads table{width:100%;border-collapse:collapse}.manual-release-downloads th,.manual-release-downloads td{padding:.65rem .8rem;text-align:left;vertical-align:top;border-bottom:1px solid #cbdad3}.manual-release-downloads th:first-child,.manual-release-downloads td:first-child{padding-left:0}.manual-release-downloads th:last-child,.manual-release-downloads td:last-child{padding-right:0}@media(max-width:650px){.manual-release-downloads thead{display:none}.manual-release-downloads tr{display:block;padding:.8rem 0;border-bottom:1px solid #cbdad3}.manual-release-downloads td{display:block;padding:.15rem 0;border:0}.manual-release-downloads td:first-child{font-weight:700}}</style><section class="manual-related manual-release-downloads" id="classroom-downloads"><h2>Course downloads</h2><p>Choose <strong>one complete ZIP for your computer</strong>. Every package contains the English manual, HTML lesson slides, all examples and its matching offline installer. Each is smaller than 250 MB.</p><div class="table-wrap"><table><thead><tr><th>Computer</th><th>Download</th><th>Size</th><th>Requirements</th></tr></thead><tbody>'+rows+'</tbody></table></div><p><a href="'+html.escape(data['release_url'],quote=True)+'">Release notes and all downloads</a>. This clean repository is private during publication review; downloads currently require repository access. Mac packages remain pilots; native Mac/Rhino acceptance is pending. No verified installer is supplied for Linux, Windows ARM or older macOS.</p></section>'
